insert into public.cancers (slug, name, summary, signs, prevention, icon, review_note) values
  ('breast', 'Breast cancer', 'Cancer that starts in the breast. Finding it early gives people a much better chance of treatment.', ARRAY['A new lump in the breast or underarm', 'Change in breast size or shape', 'Skin dimpling or nipple discharge']::text[], ARRAY['Know what is normal for your body', 'Ask about screening from age 40, or earlier if your family has had breast cancer', 'See a health worker if you notice a new lump']::text[], 'volunteer_activism', 'placeholder, needs review'),
  ('cervical', 'Cervical cancer', 'Cancer of the cervix. Screening and the HPV vaccine can prevent most cases.', ARRAY['Bleeding after sex or between periods', 'Unusual vaginal discharge', 'Pain in the pelvis']::text[], ARRAY['HPV vaccine for girls and boys when offered', 'Regular screening (VIA or Pap) as advised locally', 'Do not ignore unusual bleeding']::text[], 'health_and_safety', 'placeholder, needs review'),
  ('prostate', 'Prostate cancer', 'Cancer of the prostate gland. It is more common in older men and can grow slowly.', ARRAY['Trouble passing urine', 'Getting up often at night to urinate', 'Blood in urine or semen']::text[], ARRAY['Talk to a health worker from age 50, or earlier with family history', 'Do not ignore urine changes', 'Ask about a simple blood test (PSA) if offered']::text[], 'male', 'placeholder, needs review'),
  ('liver', 'Liver cancer', 'Cancer that starts in the liver. Hepatitis vaccination and avoiding aflatoxins help lower risk.', ARRAY['Pain on the right side of the belly', 'Yellow skin or eyes', 'Unexplained weight loss']::text[], ARRAY['Hepatitis B vaccine', 'Store grains and groundnuts dry to reduce mould', 'Limit alcohol and seek care for hepatitis']::text[], 'ecg_heart', 'placeholder, needs review'),
  ('colorectal', 'Colorectal cancer', 'Cancer of the colon or rectum. Screening and early care save lives.', ARRAY['Blood in the stool', 'A change in bowel habits that lasts', 'Belly pain or unexplained weight loss']::text[], ARRAY['Eat more fibre from plants', 'Stay active', 'Ask about screening if you are 50 or older, or have family history']::text[], 'gastroenterology', 'placeholder, needs review');
insert into public.myths (id, cancer, myth, why_people_believe, fact, what_to_do, source, age_level, audio_url, review_note) values
  ('breast-myth-1', 'breast', 'A lump in the breast always means cancer.', 'People hear stories of lumps that turned out to be cancer.', 'Many lumps are not cancer. Only a health worker can check. Still, every new lump should be examined.', 'See a clinic if you find a new lump. Do not wait at home in fear.', 'placeholder, needs review', 'adults', '', 'placeholder, needs review'),
  ('breast-myth-2', 'breast', 'Breast cancer is a curse or punishment.', 'Illness is sometimes explained through spiritual blame.', 'Breast cancer is a disease of cells. It is not a curse. Treatment and support exist.', 'Seek medical care and kind support. You are not to blame.', 'placeholder, needs review', 'adults', '', 'placeholder, needs review'),
  ('cervical-myth-1', 'cervical', 'Only women who have many partners get cervical cancer.', 'People link the cervix only to sexual behaviour.', 'HPV is common. Most sexually active people meet it. Screening and vaccines protect everyone who needs them.', 'Get screened when invited. Ask about the HPV vaccine for young people in your family.', 'placeholder, needs review', 'adults', '', 'placeholder, needs review'),
  ('cervical-myth-2', 'cervical', 'If I feel well, I do not need a cervical screening.', 'People wait for pain before they visit a clinic.', 'Early cervical changes often have no pain. Screening finds them before they become cancer.', 'Go for screening even if you feel fine. Ask a nurse when you are due.', 'placeholder, needs review', 'adults', '', 'placeholder, needs review'),
  ('prostate-myth-1', 'prostate', 'Prostate problems are just old age and cannot be treated.', 'Urine changes are common in older men, so people ignore them.', 'Some urine changes are not cancer, but some are. A health worker can check and treat many problems.', 'Tell a clinic if passing urine becomes hard, painful, or bloody.', 'placeholder, needs review', 'elders', '', 'placeholder, needs review'),
  ('prostate-myth-2', 'prostate', 'Talking about the prostate is shameful for men.', 'Men are often told to stay silent about the body.', 'Silence delays care. Prostate cancer found early is often treatable.', 'Talk to a trusted health worker. Bring a friend if that feels easier.', 'placeholder, needs review', 'adults', '', 'placeholder, needs review'),
  ('liver-myth-1', 'liver', 'Yellow eyes always mean witchcraft.', 'Jaundice looks sudden and frightening.', 'Yellow skin or eyes can be a liver problem, including hepatitis or cancer. It needs a clinic, not blame.', 'Go to a health facility the same week you notice yellow eyes or skin.', 'placeholder, needs review', 'adults', '', 'placeholder, needs review'),
  ('liver-myth-2', 'liver', 'Hepatitis vaccines are only for babies and do not matter.', 'Adults think vaccines stop after childhood.', 'Hepatitis B vaccine lowers the chance of liver cancer. Ask if you still need it.', 'Ask a clinic about hepatitis B vaccination and testing.', 'placeholder, needs review', 'adults', '', 'placeholder, needs review'),
  ('colorectal-myth-1', 'colorectal', 'Blood in the stool is always haemorrhoids.', 'Haemorrhoids are common, so people self-diagnose.', 'Blood in the stool can have many causes. A health worker should check, especially if it is new or lasts.', 'Do not treat yourself for weeks. Book a clinic visit.', 'placeholder, needs review', 'adults', '', 'placeholder, needs review'),
  ('colorectal-myth-2', 'colorectal', 'Only rich countries get bowel cancer.', 'People think this cancer is a Western disease.', 'Colorectal cancer occurs in Africa too. Diet, family history, and age all matter.', 'Tell a health worker about lasting bowel changes. Ask about screening if you are 50 or older.', 'placeholder, needs review', 'adults', '', 'placeholder, needs review'),
  ('breast-myth-kids-1', 'breast', 'Only grown-ups get lumps in the chest.', 'Kids think illness is only for older people.', 'Anyone can find a new lump. Most lumps are not cancer, but a grown-up should still tell a nurse.', 'If you feel a new lump, tell a parent or teacher. Ask to see a health worker.', 'placeholder, needs review', 'kids', '', 'placeholder, needs review'),
  ('breast-myth-teens-1', 'breast', 'You do not need to check your body until you are old.', 'Teens think breast checks are only for older women.', 'Knowing what is normal for your body helps you notice a change early. A health worker can teach you.', 'Learn how your chest usually feels. Tell a clinic if you find a new lump or a change.', 'placeholder, needs review', 'teens', '', 'placeholder, needs review'),
  ('cervical-myth-kids-1', 'cervical', 'Shots are only for when you already feel sick.', 'Kids think medicine is only for pain.', 'Some shots, like the HPV vaccine when you are older, help stop illness before it starts.', 'Ask a parent about vaccines at the clinic. They keep your body safer.', 'placeholder, needs review', 'kids', '', 'placeholder, needs review'),
  ('cervical-myth-teens-1', 'cervical', 'The HPV vaccine is only for girls who have had sex.', 'People mix up HPV with blame about sex.', 'HPV is common. The vaccine works best before exposure. Boys and girls can both be protected when it is offered.', 'Ask a clinic or a trusted adult about the HPV vaccine. It is a health choice, not a judgement.', 'placeholder, needs review', 'teens', '', 'placeholder, needs review'),
  ('prostate-myth-kids-1', 'prostate', 'Boys should never talk about how they pee.', 'Kids are told that body talk is rude.', 'Peeing is a normal body job. Pain or blood is a reason to tell a grown-up, not a secret.', 'If peeing hurts or looks odd, tell a parent and see a nurse.', 'placeholder, needs review', 'kids', '', 'placeholder, needs review'),
  ('prostate-myth-teens-1', 'prostate', 'Young men never need to notice changes when they urinate.', 'People say prostate care is only for old men.', 'Prostate cancer is more common later in life, but urine pain or blood at any age should be checked.', 'Do not stay quiet. Tell a health worker if passing urine becomes hard, painful, or bloody.', 'placeholder, needs review', 'teens', '', 'placeholder, needs review'),
  ('liver-myth-kids-1', 'liver', 'Only grown-ups get sick from smoking.', 'Kids see adults smoke and think the harm is far away.', 'Smoke is not safe for anyone. It can hurt the lungs and the liver over time.', 'Stay away from smoke. Tell a grown-up if someone offers you a cigarette.', 'placeholder, needs review', 'kids', '', 'placeholder, needs review'),
  ('liver-myth-teens-1', 'liver', 'Smoking and alcohol cannot hurt you until you are old.', 'Teens think damage only shows after many years.', 'Smoke and heavy alcohol can harm the liver. Hepatitis vaccines also help protect the liver.', 'Skip smoking. Limit alcohol. Ask a clinic about hepatitis B vaccination.', 'placeholder, needs review', 'teens', '', 'placeholder, needs review'),
  ('colorectal-myth-kids-1', 'colorectal', 'Tummy pain is always from snacks, so you can ignore it.', 'Kids get tummy aches often and wait for them to pass.', 'A tummy ache that lasts, or blood in the toilet, needs a grown-up and a nurse.', 'Tell a parent if your tummy hurts for many days or if you see blood.', 'placeholder, needs review', 'kids', '', 'placeholder, needs review'),
  ('colorectal-myth-teens-1', 'colorectal', 'Checking your body is embarrassing, so skip it.', 'Teens feel shy about toilets and blood.', 'Blood in the stool or a lasting change in the toilet is a reason to see a health worker, not to hide.', 'Tell a trusted adult or a clinic. Early checks are kinder than waiting in fear.', 'placeholder, needs review', 'teens', '', 'placeholder, needs review'),
  ('general-myth-1', 'general', 'Cancer is always an immediate death sentence and cannot be cured or treated.', 'People often meet cancer late, when treatment is harder.', 'Caught early, cervical, breast, and prostate cancers can often be treated. Many people in East Africa live after care.', 'Learn the signs, get screened, and see a health worker early.', 'placeholder, needs review', 'adults', '', 'placeholder, needs review');
insert into public.quiz_questions (id, cancer, question, choices, answer, review_note) values
  ('breast-q1', 'breast', 'What should you do if you find a new lump in the breast?', ARRAY['Wait one year', 'See a health worker', 'Rub herbal oil only']::text[], 1, 'placeholder, needs review'),
  ('breast-q2', 'breast', 'Is every breast lump cancer?', ARRAY['Yes, always', 'No, but every new lump should be checked', 'Only in older women']::text[], 1, 'placeholder, needs review'),
  ('breast-q3', 'breast', 'Breast cancer is caused by a curse.', ARRAY['True', 'False', 'Only in some families']::text[], 1, 'placeholder, needs review'),
  ('cervical-q1', 'cervical', 'Can you need a cervical screening even if you feel well?', ARRAY['No', 'Yes', 'Only after childbirth']::text[], 1, 'placeholder, needs review'),
  ('cervical-q2', 'cervical', 'What helps prevent most cervical cancer?', ARRAY['HPV vaccine and screening', 'Drinking more tea', 'Avoiding cold weather']::text[], 0, 'placeholder, needs review'),
  ('cervical-q3', 'cervical', 'Unusual bleeding after sex should be ignored.', ARRAY['True', 'False', 'Only if it happens once a year']::text[], 1, 'placeholder, needs review'),
  ('prostate-q1', 'prostate', 'Who should talk to a health worker about prostate checks?', ARRAY['Only boys under 18', 'Men, especially from about age 50, or earlier with family history', 'Only women']::text[], 1, 'placeholder, needs review'),
  ('prostate-q2', 'prostate', 'Trouble passing urine is always just old age.', ARRAY['True', 'False — it should be checked', 'It never matters']::text[], 1, 'placeholder, needs review'),
  ('prostate-q3', 'prostate', 'It is okay for men to ask a clinic about urine changes.', ARRAY['True', 'False', 'Only in private hospitals']::text[], 0, 'placeholder, needs review'),
  ('liver-q1', 'liver', 'Yellow eyes or skin should be checked by a health worker.', ARRAY['True', 'False', 'Only in babies']::text[], 0, 'placeholder, needs review'),
  ('liver-q2', 'liver', 'Which vaccine helps lower the risk of liver cancer?', ARRAY['Hepatitis B vaccine', 'Tetanus only', 'There is no vaccine']::text[], 0, 'placeholder, needs review'),
  ('liver-q3', 'liver', 'Damp, mouldy groundnuts and maize are safe to eat in large amounts.', ARRAY['True', 'False — mould can harm the liver', 'Only if cooked twice']::text[], 1, 'placeholder, needs review'),
  ('colorectal-q1', 'colorectal', 'Blood in the stool should be checked.', ARRAY['Never', 'Yes, see a health worker', 'Only in children']::text[], 1, 'placeholder, needs review'),
  ('colorectal-q2', 'colorectal', 'A lasting change in bowel habits can be a reason to visit a clinic.', ARRAY['True', 'False', 'Only after two years']::text[], 0, 'placeholder, needs review'),
  ('colorectal-q3', 'colorectal', 'Colorectal cancer never happens in Africa.', ARRAY['True', 'False', 'Only in coastal cities']::text[], 1, 'placeholder, needs review');
insert into public.survivors (id, name, cancer, language, country, city, story, voice_url, is_demo, review_note) values
  ('survivor-amina', 'Amina K.', 'breast', ARRAY['English']::text[], 'Rwanda', 'Kigali', 'I waited because I was afraid. A nurse at a Kigali clinic listened, and I started treatment. I still have hard days, but I am here.', '', true, 'placeholder, needs review'),
  ('survivor-jean', 'Jean P.', 'prostate', ARRAY['English']::text[], 'Rwanda', 'Kigali', 'I thought urine trouble was only age. My son took me to CHUK. Early checks made care possible. I talk to other men now so they do not stay silent.', '', true, 'placeholder, needs review'),
  ('survivor-claire', 'Claire N.', 'cervical', ARRAY['English']::text[], 'Rwanda', 'Kigali', 'Screening found a change before I felt sick. Treatment was scary, but the circle of women around me kept me going.', '', true, 'placeholder, needs review'),
  ('survivor-eric', 'Eric M.', 'colorectal', ARRAY['English']::text[], 'Rwanda', 'Kigali', 'I ignored blood in the stool until my sister insisted. I am recovering and I want others to ask for help sooner than I did.', '', true, 'placeholder, needs review');
insert into public.support_groups (id, name, cancer, language, city, country, whatsapp_link, lat, lng, moderator, review_note) values
  ('group-kigali-breast', 'Kigali Breast Care Circle', 'breast', 'English', 'Kigali', 'Rwanda', 'https://wa.me/250700000001', -1.9441, 30.0619, 'Demo moderator', 'placeholder, needs review'),
  ('group-kigali-cervical', 'Gasabo Cervical Support', 'cervical', 'English', 'Kigali', 'Rwanda', 'https://wa.me/250700000002', -1.932, 30.106, 'Demo moderator', 'placeholder, needs review'),
  ('group-kigali-all', 'Menya All-Cancers Evening Circle', 'general', 'English', 'Kigali', 'Rwanda', 'https://wa.me/250700000003', -1.958, 30.112, 'Demo moderator', 'placeholder, needs review');
insert into public.organisations (id, name, offers, who_qualifies, how_to_apply, country, city, lat, lng, website, verified, review_note) values
  ('org-chuk', 'University Teaching Hospital of Kigali (CHUK)', ARRAY['screening', 'treatment', 'support']::text[], 'People referred for specialist care in Kigali.', 'Go to the casualty or outpatient desk, or arrive with a referral letter.', 'Rwanda', 'Kigali', -1.9586, 30.0614, 'https://chuk.rw', true, 'placeholder, needs review'),
  ('org-rbc', 'Rwanda Biomedical Centre', ARRAY['screening', 'vaccines', 'support']::text[], 'National programmes; ask your local health centre.', 'Ask a community health worker or district hospital about current campaigns.', 'Rwanda', 'Kigali', -1.9437, 30.0594, 'https://rbc.gov.rw', true, 'placeholder, needs review'),
  ('org-kfh', 'King Faisal Hospital Kigali', ARRAY['screening', 'treatment']::text[], 'Patients who can book oncology and diagnostic services.', 'Call the hospital switchboard or visit the outpatient department.', 'Rwanda', 'Kigali', -1.9448, 30.0922, 'https://kfh.rw', true, 'placeholder, needs review'),
  ('org-butaro', 'Butaro Cancer Centre of Excellence (Kigali liaison)', ARRAY['treatment', 'support']::text[], 'People who need cancer treatment; many are referred from district hospitals.', 'Ask your district hospital for a referral. This Kigali pin is a placeholder liaison point.', 'Rwanda', 'Kigali', -1.95, 30.06, 'https://www.pih.org', true, 'placeholder, needs review'),
  ('org-mutuelle-kacyiru', 'Kacyiru Health Centre', ARRAY['screening', 'vaccines', 'free drugs']::text[], 'People living nearby, including Mutuelle de Santé holders.', 'Bring your Mutuelle card or national ID to the reception desk.', 'Rwanda', 'Kigali', -1.9356, 30.0806, '', true, 'placeholder, needs review');
